"""Complete 40 original systemic sclerosis, myositis and overlap questions."""
from create_rheum_sclerosis_muscle import rows,q,E,B,I,MY,MC,IBM,ref
from qbank_authoring import finalize
CA=ref('IMACS international myositis-associated cancer screening guideline','https://doi.org/10.1038/s41584-023-01045-w')
IL=ref('ERS/EULAR CTD-associated ILD guideline: 2026','https://publications.ersnet.org/content/erj/67/1/2402533')

q('An adult with new dermatomyositis has anti-TIF1-gamma antibodies. Which additional assessment is especially important?', 'Risk-stratified malignancy screening',[
 ('Screening only for iron overload','This does not address the characteristic cancer association.'),('Excluding all cancer risk because the rash is autoimmune','An autoimmune phenotype does not rule out associated malignancy.'),('Routine coronary angiography as the antibody-specific screening test','This is not the defining anti-TIF1-gamma association.')],
 'Cancer risk differs across myositis phenotypes','**Adult dermatomyositis with anti-TIF1-gamma is a high-risk cancer-associated phenotype.**',['Age, dysphagia, refractory activity and skin necrosis can further influence risk.','Testing should follow risk-stratified guidance alongside ordinary age- and sex-appropriate screening.'], '**Look for cancer symptoms and document a screening plan.**',['Do not interpret an antibody as proof that cancer is present.','Follow-up screening decisions depend on timing from myositis onset and the individual risk category.'],[['Anti-TIF1-gamma','Important cancer-risk marker'],['Clinical features','Modify risk'],['Screening','Risk-stratified rather than identical for all']],[CA],style='clinical_scenario')

q('Which antibody is most directly associated with an immune-mediated necrotizing myopathy phenotype?', 'Anti-SRP',[
 ('Anti-centromere','This is associated with systemic sclerosis rather than the defining necrotizing myopathy phenotype.'),('Anti-dsDNA','This is associated with SLE and is not an IMNM-specific antibody.'),('Anti-La/SSB','This is associated with other connective-tissue disease contexts.')],
 'Recognize antibody-defined necrotizing myopathy','**Anti-SRP can accompany severe symmetric proximal weakness and markedly elevated CK.**',['Anti-HMGCR is another major IMNM antibody.','The biopsy often emphasizes necrosis and regeneration rather than a dense inflammatory infiltrate.'], '**Assess severity and begin specialist-directed treatment.**',['Check swallowing, respiratory involvement and functional impairment.','Follow strength as well as CK because biochemical improvement may precede full functional recovery.'],[['Anti-SRP','IMNM association'],['Anti-HMGCR','Another IMNM group'],['Strength and CK','Complementary outcomes']],[ref('Anti-SRP IMNM: clinical characterization','https://pubmed.ncbi.nlm.nih.gov/36311711/'),MY])

q('Which muscle biopsy feature is classically associated with dermatomyositis?', 'Perifascicular atrophy with a compatible inflammatory microvascular pattern',[
 ('Rimmed vacuoles with the characteristic finger-flexor/quadriceps phenotype','This supports inclusion body myositis.'),('Widespread necrosis/regeneration with limited inflammation in anti-HMGCR disease','This supports immune-mediated necrotizing myopathy.'),('Predominant type II fiber atrophy without an inflammatory pattern during chronic steroid exposure','This supports steroid myopathy in the appropriate setting.')],
 'Match pathology to the clinical phenotype','**Perifascicular pathology is an important dermatomyositis clue.**',['Pathology can vary by subtype, disease stage and treatment.','A biopsy should be interpreted with skin findings, antibody results and weakness distribution.'], '**Do not diagnose a subtype from one nonspecific finding.**',['Inclusion body, necrotizing and overlap myopathies have different implications.','Appropriate sampling and specialist pathology review improve diagnostic yield.'],[['DM','Perifascicular changes'],['IBM','Rimmed vacuoles plus clinical pattern'],['IMNM','Necrosis/regeneration']],[MC,MY])

q('Which statement best describes current treatment of typical sporadic inclusion body myositis?', 'Supportive rehabilitation, mobility and swallowing care are central because standard immunosuppression has not shown reliable disease-modifying benefit',[
 ('High-dose prednisone reliably reverses the usual IBM course','Typical IBM often responds poorly to standard immunosuppression.'),('Rituximab is established curative treatment for every patient','No such universal curative benefit is established.'),('Exercise must be permanently avoided','Adapted activity and rehabilitation support safety and function.')],
 'Do not extrapolate dermatomyositis treatment efficacy to IBM','**IBM has inflammatory and degenerative features with limited response to conventional immune treatment.**',['Falls, loss of hand function and dysphagia require practical intervention.','Selected dysphagia interventions do not imply reversal of the entire disease course.'], '**Plan rehabilitation and complication surveillance early.**',['Consider assistive devices, swallowing assessment and nutritional support as appropriate.','Reassess an atypical course or apparent dramatic immune response for an alternative diagnosis.'],[['IBM','Limited established immune-treatment benefit'],['Rehabilitation','Core management'],['Dysphagia','Requires active assessment']],[IBM])

q('Which treatment has randomized phase 3 evidence of benefit in active adult dermatomyositis and can be considered in selected severe or refractory disease?', 'Intravenous immunoglobulin',[
 ('Allopurinol','This treats urate biology, not dermatomyositis.'),('Bosentan','It is not an established muscle-directed DM treatment.'),('Hydroxychloroquine alone as an equivalent treatment for severe muscle weakness','It may help skin disease but is not equivalent therapy for severe myositis.')],
 'Use immune globulin where the evidence and severity justify it','**ProDERM demonstrated efficacy of IVIG in adult active dermatomyositis.**',['It can be useful in selected severe muscle or swallowing disease and refractory manifestations.','Thromboembolic, renal and infusion risks need assessment.'], '**Measure functional response and treatment burden.**',['A positive trial does not mean every new myositis patient requires IVIG.','Plan concomitant disease control and reassessment rather than indefinite treatment without an outcome target.'],[['IVIG','Evidence in active DM'],['Severe dysphagia','Potential selected indication'],['Safety','Thrombosis, renal and infusion risks']],[ref('ProDERM randomized trial','https://www.nejm.org/doi/full/10.1056/NEJMoa2117912'),MY])

q('A patient with dermatomyositis coughs during meals, loses weight and has recurrent aspiration pneumonia. What is the most appropriate next assessment?', 'Urgent formal swallowing and nutritional assessment alongside disease treatment',[
 ('Assume reflux alone and defer swallowing assessment','Oropharyngeal weakness and aspiration need direct assessment.'),('Use CK normalization alone to certify safe swallowing','Biochemical improvement does not prove adequate airway protection.'),('Recommend unrestricted oral intake to strengthen the muscles despite aspiration','This can worsen harm and should not replace a safe feeding plan.')],
 'Bulbar involvement can threaten nutrition and the airway','**Dysphagia in myositis requires assessment of aspiration and safe intake.**',['Speech/swallow specialists and instrumental testing can define the problem.','Severe disease may need temporary enteral support and intensified immune treatment.'], '**Treat the underlying disease and protect the patient during recovery.**',['Assess respiratory status and infection.','Swallowing outcomes should be followed independently of serum enzymes.'],[['Aspiration','Immediate safety concern'],['Nutrition','Assess intake and weight'],['Disease treatment','May need escalation']],[MY],style='clinical_scenario')

q('A patient with inflammatory myopathy has elevated AST and ALT together with CK 7,000 U/L and normal bilirubin. Which interpretation is appropriate?', 'Muscle injury may contribute to aminotransferase elevation; assess hepatic and muscular sources rather than assuming liver disease',[
 ('AST and ALT can never originate from muscle','Both can rise with muscle injury, especially AST.'),('The enzymes prove viral hepatitis regardless of other findings','Etiology requires context and additional evaluation.'),('A normal bilirubin excludes every possible liver disorder','Normal bilirubin does not rule out all hepatic pathology.')],
 'Do not mistake muscle enzymes for an isolated liver diagnosis','**Aminotransferases can rise during active myocyte injury.**',['CK, aldolase, LDH, bilirubin, GGT and the clinical context can help localize the source.','Muscle and liver disease can coexist.'], '**Avoid unnecessary or unsafe decisions based on a single marker.**',['Review medications and hepatotoxic exposures.','Follow the enzyme pattern as muscle activity changes while investigating genuine hepatic clues.'],[['CK','Supports muscle injury'],['GGT/bilirubin','Adds hepatic context'],['AST/ALT','Not exclusively liver-derived']],[MY],style='clinical_scenario')

q('Which rehabilitation principle is recommended for most patients with inflammatory myopathy?', 'An individualized, appropriately supervised exercise program adapted to activity and capacity',[
 ('Permanent complete bed rest to prevent any enzyme increase','Prolonged inactivity worsens deconditioning and function.'),('Maximal unmonitored resistance exercise during severe unstable disease','Exercise intensity must reflect clinical stability and professional assessment.'),('Strengthening only after every antibody becomes negative','Antibody negativity is not a prerequisite for rehabilitation.')],
 'Preserve function while controlling inflammation','**Adapted aerobic and resistance activity is part of myositis care.**',['The program should account for weakness, cardiopulmonary disease and falls risk.','Disease control and rehabilitation are complementary rather than mutually exclusive.'], '**Set measurable functional goals.**',['Monitor tolerance and adjust during acute deterioration.','Include occupational support and assistive strategies where needed.'],[['Program','Individualized and supervised'],['Active severe disease','Adapt intensity and safety'],['Goal','Function and participation']],[MY])

q('A patient with suspected anti-MDA5 dermatomyositis develops rapidly increasing oxygen requirement and diffuse ILD. Which initial treatment principle is supported by ACR/CHEST guidance?', 'Urgent up-front combination immunosuppression rather than a slow sequential monotherapy approach',[
 ('Wait for severe proximal weakness before treating the lung disease','The lung syndrome can be severe with little muscle involvement.'),('Use an NSAID alone while awaiting several months of progression','This is inadequate for rapidly progressive organ-threatening ILD.'),('Use methotrexate alone as standard induction for anti-MDA5 RP-ILD','This is not the recommended induction approach for this emergency.')],
 'Rapidly progressive ILD is an emergency phenotype','**Guidance conditionally favors up-front combination therapy, including triple therapy for suspected or confirmed MDA5-associated RP-ILD.**',['Regimen selection is specialist-led and may use glucocorticoids with other potent agents.','Infection must be assessed and managed in parallel.'], '**Escalate organ support and consider early transplant-center referral when appropriate.**',['Evidence certainty is limited, so individual risks matter.','Do not manage this as routine slowly progressive fibrotic disease.'],[['RP-ILD','Urgent multidisciplinary care'],['MDA5 phenotype','Up-front combination strategy'],['Infection','Parallel evaluation/treatment']],[ref('ACR/CHEST RP-ILD treatment recommendation','https://rheumatology.org/api/asset/bltaedebda97a351d47'),IL],style='clinical_scenario')

q('A patient has classic dermatomyositis skin findings for months without objective weakness or muscle enzyme elevation. Which statement is correct?', 'Clinically amyopathic dermatomyositis remains possible and still requires systemic risk assessment',[
 ('Dermatomyositis is impossible without a high CK','Amyopathic disease is recognized.'),('Absence of muscle weakness excludes ILD and cancer associations','Extramuscular risks can remain important.'),('All skin-only dermatomyositis must be reclassified as systemic sclerosis','The skin morphology and systemic assessment determine the diagnosis.')],
 'Muscle sparing does not remove the systemic phenotype','**Clinically amyopathic DM has characteristic skin disease without overt clinical muscle involvement.**',['Subclinical muscle findings may lead to a hypomyopathic designation.','Autoantibody profile and clinical features guide ILD and malignancy risk assessment.'], '**Treat the skin and screen the relevant organs.**',['Photoprotection and specialist-directed therapy are important.','Reassess if weakness, dysphagia or respiratory symptoms develop.'],[['Amyopathic','No overt muscle disease'],['Hypomyopathic','Subclinical muscle abnormalities'],['Risk assessment','Still includes lung and malignancy domains']],[MC,MY,CA],style='clinical_scenario')

q('Raynaud phenomenon, puffy hands, inflammatory arthritis, myositis and high-titer anti-U1 RNP suggest which overlap phenotype?', 'Mixed connective tissue disease',[
 ('Antisynthetase syndrome defined by anti-Jo-1','That syndrome requires a different characteristic antibody family and phenotype.'),('Anti-centromere limited cutaneous systemic sclerosis alone','The described multisystem overlap and RNP association support MCTD more strongly.'),('Primary antiphospholipid syndrome','This does not explain the muscle/arthritis/puffy-hand overlap pattern.')],
 'Interpret anti-U1 RNP with an overlap phenotype','**MCTD combines features from several systemic autoimmune rheumatic diseases with a characteristic RNP association.**',['Anti-U1 RNP alone is not sufficient for every proposed classification framework.','Other established connective-tissue diseases can also have RNP antibodies.'], '**Assess the active organs rather than treat the label alone.**',['Evaluate ILD, pulmonary hypertension, muscle disease and swallowing symptoms.','Longitudinal follow-up can clarify an evolving phenotype.'],[['RNP plus overlap','Supports MCTD'],['RNP alone','Not sufficient'],['Treatment','Organ- and severity-directed']],[ref('Early MCTD diagnosis: clinical and laboratory assessment','https://pmc.ncbi.nlm.nih.gov/articles/PMC10387239/'),IL])

q('Which cardiopulmonary complication is an important cause of morbidity and mortality in mixed connective tissue disease?', 'Pulmonary arterial hypertension',[
 ('Isolated uncomplicated allergic rhinitis','This does not carry the same organ-threatening implication.'),('A congenital ventricular septal defect newly caused by RNP antibodies','This is not an acquired MCTD complication.'),('Routine asymptomatic sinus bradycardia as the defining pulmonary vascular lesion','This does not define PAH.')],
 'Screen the pulmonary vascular as well as interstitial compartment','**MCTD can produce both ILD and pulmonary hypertension.**',['Unexplained dyspnea or a disproportionate DLCO fall requires assessment.','Hemodynamic confirmation identifies the PH subtype when indicated.'], '**Do not attribute all breathlessness to muscle weakness.**',['Use pulmonary function, imaging and cardiac testing according to the presentation.','Coordinate specialty care for confirmed PAH.'],[['ILD','Parenchymal mechanism'],['PAH','Pulmonary vascular mechanism'],['Muscle weakness','Another possible respiratory contributor']],[IL,ref('ESC/ERS pulmonary hypertension guideline','https://doi.org/10.1093/eurheartj/ehac237')])

q('Which antibody is particularly associated with systemic sclerosis–myositis overlap?', 'Anti-PM/Scl',[
 ('Anti-CCP','This is principally an RA-associated antibody.'),('Anti-beta2-glycoprotein I','This belongs to the aPL family rather than the defining scleromyositis association.'),('Anti-mitochondrial M2','This is classically associated with primary biliary cholangitis, though broader overlaps may occur.')],
 'Identify a scleromyositis-associated antibody','**Anti-PM/Scl can accompany a systemic sclerosis and inflammatory myopathy overlap.**',['The clinical phenotype, not antibody alone, determines whether muscle inflammation is present.','ILD and other systemic involvement need assessment.'], '**Balance treatment of myositis against systemic sclerosis-specific risks.**',['Glucocorticoid decisions require particular caution regarding renal crisis.','Consider steroid-sparing treatment according to the active organs.'],[['Anti-PM/Scl','Scleromyositis association'],['Muscle assessment','Strength, enzymes and selected tests'],['Therapy','Account for SSc renal risk']],[ref('Anti-PM/Scl-associated disease cohort','https://pmc.ncbi.nlm.nih.gov/articles/PMC5993182/'),B])

q('A patient has features of several connective-tissue diseases but does not yet meet a clear established disease phenotype. What is the most appropriate general strategy?', 'Document an undifferentiated/overlap phenotype and monitor and treat the manifestations actually present',[
 ('Assign a definitive diagnosis solely from any positive extractable nuclear antigen','Serology without the corresponding phenotype can misclassify patients.'),('Use intensive cyclophosphamide in every patient to prevent hypothetical future disease','Treatment intensity should match current organ involvement and risk.'),('Discharge permanently because disease cannot evolve after an initial assessment','The phenotype may change over time and merits appropriate follow-up.')],
 'Diagnostic uncertainty does not prevent organ-directed care','**An evolving or undifferentiated phenotype should be described accurately rather than forced into a label.**',['Look for current organ-threatening disease that requires treatment regardless of nomenclature.','Repeat clinical assessment is often more useful than indiscriminate repeated antibody panels.'], '**Match follow-up to the manifestations and risk.**',['Counsel on symptoms that should prompt earlier review.','Avoid exposing a mild uncertain phenotype to disproportionate treatment toxicity.'],[['Diagnosis','Describe what is established'],['Organ involvement','Determines urgency'],['Follow-up','Detect evolution']],[B,MY])

if __name__=='__main__':finalize('Rheumatology',5,'Systemic Sclerosis, Myositis and Overlap Syndromes','rheum-ssc-myositis',rows,40)
